export interface WebMenuItem {
    readonly id: string;
    readonly label: string;
    readonly kind?: 'item' | 'heading' | 'separator';
    readonly icon?: LucideIconName | '';
    readonly badge?: string;
    readonly description?: string;
    /** Stable project page ID, resolved by the application's router. */
    readonly page?: string;
    readonly href?: string;
    readonly target?: '_self' | '_blank';
    readonly visible?: boolean;
    readonly disabled?: boolean;
    readonly expanded?: boolean;
    readonly children?: readonly WebMenuItem[];
}

export interface WebMenuBrand {
    readonly visible: boolean;
    readonly caption: string;
    readonly subtitle: string;
    readonly logo: string;
    readonly logoSize: number;
    readonly page: string;
    readonly href: string;
}

export interface WebMenuUser {
    readonly visible: boolean;
    readonly name: string;
    readonly description: string;
    readonly avatar: string;
    readonly status: 'none' | 'online' | 'away' | 'busy';
}

export interface WebMenuAppearance {
    readonly background: string;
    readonly foreground: string;
    readonly muted: string;
    readonly border: string;
    readonly hoverBackground: string;
    readonly activeBackground: string;
    readonly activeForeground: string;
    readonly accent: string;
    readonly badgeBackground: string;
    readonly badgeForeground: string;
    readonly itemHeight: number;
    readonly itemRadius: number;
    readonly itemGap: number;
    readonly iconSize: number;
    readonly fontSize: number;
    readonly padding: number;
    readonly indent: number;
    readonly collapsedWidth: number;
}

export interface WebMenuConfiguration {
    readonly schemaVersion: 1;
    readonly orientation: 'vertical' | 'horizontal';
    readonly accessibleLabel: string;
    readonly collapsible: boolean;
    readonly collapsed: boolean;
    readonly accordion: boolean;
    readonly searchable: boolean;
    readonly themeToggle: boolean;
    /** Filter while typing, or emit OnSearch when the user presses Enter. */
    readonly searchMode: 'filter' | 'event';
    readonly searchPlaceholder: string;
    readonly emptyText: string;
    readonly footerText: string;
    readonly selectedItemId: string;
    /** Browser viewport width in CSS pixels, independent of the sidebar width. */
    readonly mobileBreakpoint: number;
    readonly drawerWidth: number;
    readonly drawerSide: 'left' | 'right';
    readonly closeOnSelect: boolean;
    readonly brand: WebMenuBrand;
    readonly user: WebMenuUser;
    readonly appearance: WebMenuAppearance;
    readonly items: readonly WebMenuItem[];
}

export interface WebMenuSearchEvent {
    readonly text: string;
}

export interface WebMenuItemEvent {
    readonly item: WebMenuItem;
    readonly itemId: string;
    readonly path: readonly string[];
}

export interface WebMenuStateEvent {
    readonly collapsed: boolean;
    readonly open: boolean;
}

export interface WebMenuItemToggleEvent extends WebMenuItemEvent {
    readonly expanded: boolean;
}

export const WEB_MENU_THEMES: Readonly<Record<'light' | 'dark', WebMenuAppearance>>;

export function createDefaultWebMenuConfiguration(): WebMenuConfiguration;

/** A saved appearance can follow project themes while fixed presets stay available. */
export function createProjectWebMenuAppearance(appearance?: WebMenuAppearance): WebMenuAppearance;

/** Accepts relative, HTTP(S), mail and telephone links; rejects executable schemes. */
export function isWebMenuLink(value: string, image?: boolean): boolean;

/** Strict browser-safe parser used by serialization, the Inspector and runtime. */
export function parseWebMenuConfiguration(value: unknown): WebMenuConfiguration;

export function webMenuItemPath(items: readonly WebMenuItem[], id: string, path?: readonly string[]): readonly WebMenuItem[];

export interface WebMenuOptions {
    /** Static projections still use the identical DOM and appearance. */
    readonly interactive?: boolean;
    readonly viewportWidth?: number;
    /** Allows embedded previews to change their local theme without changing the application. */
    readonly onThemeToggle?: () => void;
}

/** Responsive navigation with per-instance state, disclosure submenus and a modal mobile drawer. */
export class WebMenu extends WebComponent<HTMLElement> {
    #private;
    /** Apply the saved placement before the authored subclass constructor runs. */
    static createDefinition(element: HTMLElement, factory: (element: HTMLElement) => WebMenu, initialize: (menu: WebMenu) => void): WebMenu;
    /** Resolve the concrete authored Menu already mounted for this element. */
    static fromElement<T extends WebMenu>(element: HTMLElement, menuClass: new (element: HTMLElement) => T): T;
    /** Shared handlers precede the containing page's ordinary event bindings. */
    protected bindDefinitionEvent(eventName: string, handlerName: string): void;
    emit(eventName: string, detail?: unknown): boolean;
    get floatingZIndex(): number;
    get margin(): number;
    get marginTop(): number;
    set marginTop(value: number);
    get marginRight(): number;
    set marginRight(value: number);
    get marginBottom(): number;
    set marginBottom(value: number);
    get marginLeft(): number;
    set marginLeft(value: number);
    set margin(value: number);
    get placement(): 'floating';
    get floatingHorizontalAnchor(): 'left' | 'center' | 'right';
    set floatingHorizontalAnchor(value: 'left' | 'center' | 'right');
    get floatingVerticalAnchor(): 'top' | 'center' | 'bottom';
    set floatingVerticalAnchor(value: 'top' | 'center' | 'bottom');
    constructor(element: HTMLElement, options?: WebMenuOptions);
    get configuration(): WebMenuConfiguration;
    get enabled(): boolean;
    set enabled(value: boolean);
    set configuration(value: WebMenuConfiguration);
    get items(): readonly WebMenuItem[];
    set items(value: readonly WebMenuItem[]);
    get orientation(): WebMenuConfiguration['orientation'];
    set orientation(value: WebMenuConfiguration['orientation']);
    get brand(): WebMenuConfiguration['brand'];
    set brand(value: WebMenuConfiguration['brand']);
    get user(): WebMenuConfiguration['user'];
    set user(value: WebMenuConfiguration['user']);
    get appearance(): WebMenuConfiguration['appearance'];
    set appearance(value: WebMenuConfiguration['appearance']);
    get selectedItemId(): string;
    set selectedItemId(value: string);
    get collapsed(): boolean;
    set collapsed(value: boolean);
    get isOpen(): boolean;
    get isMobile(): boolean;
    get searchMode(): WebMenuConfiguration['searchMode'];
    get themeToggle(): boolean;
    set themeToggle(value: boolean);
    set searchMode(value: WebMenuConfiguration['searchMode']);
    get searchText(): string;
    set searchText(value: string);
    findItem(id: string): WebMenuItem | undefined;
    updateItem(id: string, changes: Partial<Omit<WebMenuItem, 'id'>>): void;
    expandItem(id: string): void;
    collapseItem(id: string): void;
    toggleItem(id: string): void;
    focusItem(id: string): void;
    activateItem(id: string): void;
    open(): void;
    close(): void;
    toggle(): void;
    dispose(): void;
}
